    options: compilerOptions,
  });
  const diagnostics = [
    ...program.getOptionsDiagnostics(),
    ...program.getGlobalDiagnostics(),
    ...program.getSyntacticDiagnostics(),
    ...program.getSemanticDiagnostics(),
  ];
  const byFile = {};
  for (const file of files) {
    const sf = program.getSourceFile(file);
    const rel = path.relative(root, file);
    byFile[rel] = {
      exists: Boolean(sf),
      semantic: [],
      suggestions: [],
    };
    if (!sf) continue;
    for (const d of diagnostics) {
      if (d.file && d.file.fileName === sf.fileName) {
        const {line, character} = sf.getLineAndCharacterOfPosition(d.start || 0);
        byFile[rel].semantic.push({
          code: d.code,
          category: ts.DiagnosticCategory[d.category],
          line: line + 1,
          col: character + 1,
          message: ts.flattenDiagnosticMessageText(d.messageText, '\n'),
        });
      }
    }
    for (const d of program.getSuggestionDiagnostics(sf)) {
      const {line, character} = sf.getLineAndCharacterOfPosition(d.start || 0);
      byFile[rel].suggestions.push({
        code: d.code,
        line: line + 1,
        col: character + 1,
        message: ts.flattenDiagnosticMessageText(d.messageText, '\n'),
      });
    }
  }
  return {configErrors: parsed.errors.map(d => ts.flattenDiagnosticMessageText(d.messageText, '\n')), byFile};
}

const extra = changed.filter(file => file.includes('__tests__'));
const current = collect(changed, extra);
